import { CHAIN, CONTRACTS } from './chain-config.js';
import { createRevealPreparation } from './reveal-preparation.js';
import { loadBafResolutionSnapshot } from './baf-resolution.js';
import { loadDecimatorDrawSnapshot } from './decimator-draw-data.js';
import { prepareDecimatorReplay } from '../craps/decimator-replay.js';
import { fetchProfiles } from './profiles.js';

const key = ({ level, player }) => `${CHAIN.id}:${CONTRACTS.GAME}:${String(player).toLowerCase()}:${level}`;
const baf = createRevealPreparation({ complete: value => value?.preparationComplete === true });
const decimator = createRevealPreparation({ complete: value => value?.ranked
  && value.winners.length === value.winnerCount && value.preparedReplay });

export async function prepareBafResolution(options) {
  // An overlay closing must not cancel a shared Pending prefetch. Its own
  // generation guard still prevents the completed read from mounting late.
  const snapshot = await baf.get(key(options), () => loadBafResolutionSnapshot({ ...options, signal: undefined }));
  return withConsolation(snapshot, options);
}

export function getPreparedBafResolution(options) {
  const snapshot = baf.peek(key(options));
  return snapshot ? withConsolation(snapshot, options) : null;
}

function withConsolation(snapshot, options) {
  if (String(options.consolation ?? snapshot.player.consolation ?? 0) === snapshot.player.consolation) return snapshot;
  return { ...snapshot, player: { ...snapshot.player, consolation: String(options.consolation ?? snapshot.player.consolation ?? 0) } };
}

export function prepareDecimatorResolution(options) {
  return decimator.get(key(options), async () => {
    const snapshot = await loadDecimatorDrawSnapshot(options);
    const [identity, replay] = await Promise.allSettled([
      fetchProfiles([...new Set((snapshot.battleEntries ?? snapshot.winners)
        .map(row => row.address).filter(Boolean))]),
      prepareDecimatorReplay(snapshot),
    ]);
    return { ...snapshot, profiles: identity.status === 'fulfilled' ? identity.value : new Map(),
      preparedReplay: replay.status === 'fulfilled' ? replay.value : null };
  });
}
